1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	import threading
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "OpenSurvey"
14	RESOURCE = "surveys"
15	MAX_BODY_BYTES = 10 * 1024 * 1024
16	QUESTION_TYPES = ("text", "single_choice")
17	
18	PAGE = r"""<!doctype html>
19	<html lang="zh-CN">
20	<meta charset="utf-8">
21	<meta name="viewport" content="width=device-width,initial-scale=1">
22	<title>OpenSurvey · 问卷调查与反馈管理</title>
23	<style>
24	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
25	*{box-sizing:border-box}
26	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
27	a{color:var(--blue)}
28	h1{margin-bottom:.2rem}
29	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
30	.muted{color:var(--grey);font-size:.92rem}
31	ul.plain{list-style:none;padding-left:0}
32	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
33	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
34	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
35	textarea{resize:vertical}
36	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
37	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
38	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
39	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
40	.q-index{font-weight:700}
41	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
42	.tag.required{background:#fdecea;color:var(--red)}
43	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
44	.spacer{flex:1}
45	button{font:inherit;cursor:pointer}
46	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
47	.btn.secondary{background:#fff;color:var(--blue)}
48	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
49	.link.danger{color:var(--red)}
50	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
51	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
52	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
53	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
54	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
55	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
56	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
57	.invalid{border-color:var(--red)!important;background:#fdf6f5}
58	.detail-meta{color:var(--grey);font-size:.9rem}
59	.detail-desc,.opt-text-display{white-space:pre-wrap}
60	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
61	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
62	.q-list>li{margin:1rem 0}
63	.q-list .q-line{font-weight:600}
64	.q-list ol{margin:.4rem 0 0 1.4rem}
65	</style>
66	<main>
67	<h1>OpenSurvey</h1>
68	<p>问卷调查与反馈管理</p>
69	<div id="app"></div>
70	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
71	</main>
72	<script>
73	"use strict";
74	const app = document.getElementById("app");
75	
76	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
77	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
78	// 返回也必须丢弃，不能覆盖用户当前所在页面。
79	let activeView = 0;
80	
81	function h(tag, attrs, ...children) {
82	  const el = document.createElement(tag);
83	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
84	    if (v === null || v === undefined) continue;
85	    if (k === "class") el.className = v;
86	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
87	    else el.setAttribute(k, v);
88	  }
89	  for (const child of children.flat()) {
90	    if (child === null || child === undefined) continue;
91	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
92	  }
93	  return el;
94	}
95	
96	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
97	
98	function buildSurveyForm(existing, hooks, view) {
99	  const mode = existing ? "edit" : "create";
100	
101	  const banner = h("div", {class: "banner", id: "form-banner"});
102	  banner.hidden = true;
103	
104	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
105	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
106	  const titleErr = h("p", {class: "field-err", id: "title-err"});
107	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
108	  const qBox = h("div", {id: "questions"});
109	  const qErr = h("p", {class: "field-err", id: "questions-err"});
110	
111	  function renumber() {
112	    const cards = qBox.querySelectorAll(".q-card");
113	    cards.forEach((card, i) => {
114	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
115	      card.querySelectorAll(".opt-row").forEach((row, j) => {
116	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
117	      });
118	    });
119	  }
120	
121	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
122	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
123	  function autoGrow(el) {
124	    el.style.height = "auto";
125	    el.style.height = `${el.scrollHeight}px`;
126	  }
127	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
128	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
129	
130	  function optionRow(value) {
131	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
132	    text.addEventListener("input", () => autoGrow(text));
133	    if (value !== undefined && value !== null) { text.value = value; scheduleGrow(text); }
134	    const row = h("div", {class: "opt-row"},
135	      h("span", {class: "opt-index"}, "选项"),
136	      text,
137	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
138	    );
139	    return row;
140	  }
141	
142	  function addQuestion(type, prefill) {
143	    const isChoice = type === "single_choice";
144	    const options = h("div", {class: "options"});
145	    const card = h("div", {class: "card q-card", "data-type": type},
146	      h("div", {class: "q-head"},
147	        h("span", {class: "q-index"}, "第 N 题"),
148	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
149	        h("label", {class: "req"},
150	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
151	        h("span", {class: "spacer"}),
152	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
153	      ),
154	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
155	      h("p", {class: "field-err q-title-err"})
156	    );
157	    if (isChoice) {
158	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
159	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
160	      else options.append(optionRow(), optionRow());
161	      card.append(
162	        options,
163	        h("p", {class: "field-err opt-err"}),
164	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
165	      );
166	      card.querySelector(".add-opt").addEventListener("click", () => {
167	        options.append(optionRow());
168	        renumber();
169	        options.querySelector(".opt-row:last-child .opt-text").focus();
170	      });
171	    }
172	    const qTitleEl = card.querySelector(".q-title");
173	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
174	    if (prefill) {
175	      qTitleEl.value = prefill.title != null ? prefill.title : "";
176	      card.querySelector(".q-required").checked = !!prefill.required;
177	    }
178	    scheduleGrow(qTitleEl);
179	    qBox.append(card);
180	    renumber();
181	    if (!prefill) qTitleEl.focus();
182	    return card;
183	  }
184	
185	  function clearErrors() {
186	    banner.hidden = true;
187	    banner.replaceChildren();
188	    titleErr.textContent = "";
189	    qErr.textContent = "";
190	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
191	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
192	  }
193	
194	  function showBanner(items) {
195	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
196	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
197	    banner.hidden = false;
198	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
199	  }
200	
201	  const actionButtons = [
202	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
203	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
204	    h("span", {class: "spacer"})
205	  ];
206	  if (mode === "edit") {
207	    // 离开编辑页即丢弃全部未保存的增删与输入
208	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
209	  }
210	  actionButtons.push(h("button", {type: "submit", class: "btn"},
211	    mode === "edit" ? "保存修改" : "保存整份问卷"));
212	
213	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
214	    banner,
215	    h("section", null,
216	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
217	      mode === "edit"
218	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
219	        : null,
220	      h("label", {for: "survey-title"}, "标题"),
221	      titleInput, titleErr,
222	      h("label", {for: "survey-desc"}, "说明"),
223	      descArea,
224	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
225	      qBox, qErr,
226	      h("div", {class: "row-actions"}, actionButtons)
227	    )
228	  );
229	
230	  titleInput.addEventListener("input", () => autoGrow(titleInput));
231	  if (mode === "edit") {
232	    titleInput.value = existing.title != null ? existing.title : "";
233	    descArea.value = existing.description || "";
234	    existing.questions.forEach(question => addQuestion(question.type, question));
235	    renumber();
236	    scheduleGrow(titleInput);
237	  }
238	
239	  async function submitForm(event) {
240	    event.preventDefault();
241	    clearErrors();
242	    const problems = [];
243	
244	    const title = titleInput.value.trim();
245	    if (!title) {
246	      titleInput.classList.add("invalid");
247	      titleErr.textContent = "标题不能为空。";
248	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
249	    }
250	
251	    const cards = [...qBox.querySelectorAll(".q-card")];
252	    if (cards.length === 0) {
253	      qErr.textContent = "问卷至少需要保留一道题。";
254	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
255	    }
256	
257	    const payloadQuestions = [];
258	    cards.forEach((card, i) => {
259	      const loc = `第 ${i + 1} 题`;
260	      const titleEl = card.querySelector(".q-title");
261	      const qTitle = titleEl.value.trim();
262	      if (!qTitle) {
263	        titleEl.classList.add("invalid");
264	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
265	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
266	      }
267	      const q = {
268	        type: card.dataset.type,
269	        title: qTitle,
270	        required: card.querySelector(".q-required").checked
271	      };
272	      if (card.dataset.type === "single_choice") {
273	        const optInputs = [...card.querySelectorAll(".opt-text")];
274	        const values = optInputs.map(el => el.value.trim());
275	        const optErr = card.querySelector(".opt-err");
276	        const seen = new Set();
277	        values.forEach((val, j) => {
278	          if (!val) {
279	            optInputs[j].classList.add("invalid");
280	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
281	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
282	          } else if (seen.has(val)) {
283	            optInputs[j].classList.add("invalid");
284	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
285	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
286	          }
287	          seen.add(val);
288	        });
289	        if (values.length < 2) {
290	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
291	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
292	        }
293	        q.options = values;
294	      }
295	      payloadQuestions.push(q);
296	    });
297	
298	    if (problems.length) {
299	      showBanner(problems);
300	      return;
301	    }
302	
303	    const payload = {title, description: descArea.value, questions: payloadQuestions};
304	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
305	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
306	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
307	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
308	    const submitView = view;
309	    let resp;
310	    try {
311	      resp = await fetch(endpoint, {
312	        method: mode === "edit" ? "PUT" : "POST",
313	        headers: {"Content-Type": "application/json"},
314	        body: JSON.stringify(payload)
315	      });
316	    } catch (err) {
317	      if (submitView !== activeView) return;
318	      // 请求未成功：保留当前全部输入与增删结果
319	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
320	      return;
321	    }
322	    if (submitView !== activeView) return;
323	    let data = {};
324	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
325	    if (submitView !== activeView) return;
326	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
327	    if (saved && data.id !== undefined) {
328	      if (mode === "create") {
329	        form.reset();
330	        qBox.replaceChildren();
331	        autoGrow(titleInput);
332	        if (hooks && hooks.onCreated) hooks.onCreated();
333	      }
334	      location.hash = `#/surveys/${data.id}`;
335	      return;
336	    }
337	    // 服务端未确认保存成功：不清空任何输入，展示具体问题
338	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
339	  }
340	
341	  return form;
342	}
343	
344	/* ---------- 首页 ---------- */
345	
346	function renderHome() {
347	  const view = ++activeView;
348	  app.replaceChildren();
349	
350	  const listSection = h("section", null,
351	    h("h2", null, "问卷列表"),
352	    h("ul", {class: "plain", id: "survey-list"}, h("li", {class: "muted"}, "加载中…"))
353	  );
354	  const listEl = listSection.querySelector("#survey-list");
355	
356	  async function loadSurveys() {
357	    let data;
358	    try {
359	      const resp = await fetch("/api/surveys");
360	      data = await resp.json();
361	    } catch (err) {
362	      if (view !== activeView) return;
363	      listEl.replaceChildren(h("li", {class: "muted"}, "问卷列表加载失败。"));
364	      return;
365	    }
366	    if (view !== activeView) return;
367	    listEl.replaceChildren();
368	    if (!data.surveys.length) {
369	      listEl.append(h("li", {class: "muted"}, "还没有问卷记录。"));
370	      return;
371	    }
372	    for (const survey of data.surveys) {
373	      listEl.append(h("li", null,
374	        h("a", {href: `#/surveys/${survey.id}`}, `#${survey.id} ${survey.title}`)));
375	    }
376	  }
377	
378	  app.append(
379	    listSection,
380	    buildSurveyForm(null, {onCreated: loadSurveys}, view)
381	  );
382	  loadSurveys();
383	}
384	
385	/* ---------- 问卷详情 ---------- */
386	
387	async function renderDetail(id) {
388	  const view = ++activeView;
389	  app.replaceChildren(
390	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
391	    h("p", {class: "muted", id: "detail-status"}, "加载中…")
392	  );
393	  const status = document.getElementById("detail-status");
394	
395	  let survey;
396	  try {
397	    const resp = await fetch(`/api/surveys/${id}`);
398	    if (view !== activeView) return;
399	    if (resp.status === 404) {
400	      status.textContent = `问卷 #${id} 不存在。`;
401	      return;
402	    }
403	    if (!resp.ok) {
404	      status.textContent = `详情加载失败（HTTP ${resp.status}），请稍后重试。`;
405	      return;
406	    }
407	    survey = await resp.json();
408	  } catch (err) {
409	    if (view !== activeView) return;
410	    status.textContent = `详情加载失败：${err}`;
411	    return;
412	  }
413	  if (view !== activeView) return;
414	
415	  app.replaceChildren(
416	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
417	    h("h2", null, `#${survey.id} ${survey.title}`),
418	    h("div", {class: "row-actions"},
419	      h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿"),
420	      h("a", {class: "btn secondary", href: "#/"}, "返回首页")
421	    ),
422	    h("h3", null, "说明"),
423	    survey.description
424	      ? h("p", {class: "detail-desc"}, survey.description)
425	      : h("p", {class: "muted"}, "（无说明）"),
426	    h("h3", null, `题目（共 ${survey.questions.length} 道）`)
427	  );
428	  if (!survey.questions.length) {
429	    app.append(
430	      h("p", {class: "muted"}, "该问卷草稿还没有题目，可进入编辑补齐。"),
431	      h("p", null, h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿并添加题目"))
432	    );
433	    return;
434	  }
435	  app.append(h("ol", {class: "q-list"},
436	    survey.questions.map((q, i) => h("li", null,
437	      h("div", {class: "q-line"},
438	        `${i + 1}. ${q.title} `,
439	        h("span", {class: "tag"}, q.type === "single_choice" ? "单选题" : "文本题"),
440	        " ",
441	        h("span", {class: "tag" + (q.required ? " required" : "")}, q.required ? "必填" : "选填")
442	      ),
443	      q.options && q.options.length
444	        ? h("ol", {start: "1"}, q.options.map(opt => h("li", {class: "opt-text-display"}, opt)))
445	        : null
446	    )))
447	  );
448	}
449	
450	/* ---------- 编辑草稿 ---------- */
451	
452	function showEditLoadError(id, message, view) {
453	  // 加载失败时明确提示，绝不能用空白编辑表单覆盖已有内容
454	  if (view !== activeView) return;
455	  app.replaceChildren(
456	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
457	    h("h2", null, `编辑问卷草稿 #${id}`),
458	    h("div", {class: "banner", role: "alert"},
459	      h("strong", null, "问卷内容加载失败，未打开编辑表单："),
460	      h("p", {class: "detail-meta", style: "margin:.4rem 0 0"}, message),
461	      h("p", {style: "margin:.6rem 0 0"},
462	        h("button", {type: "button", class: "btn secondary", onclick: () => renderEdit(id)}, "重试"), " ",
463	        h("a", {class: "btn secondary", href: `#/surveys/${id}`}, "返回详情"))
464	    )
465	  );
466	}
467	
468	async function renderEdit(id) {
469	  const view = ++activeView;
470	  app.replaceChildren(
471	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
472	    h("p", {class: "muted", id: "edit-status"}, "加载中…")
473	  );
474	
475	  let survey;
476	  try {
477	    const resp = await fetch(`/api/surveys/${id}`);
478	    if (view !== activeView) return;
479	    if (resp.status === 404) {
480	      showEditLoadError(id, `问卷 #${id} 不存在。`, view);
481	      return;
482	    }
483	    if (!resp.ok) {
484	      showEditLoadError(id, `服务端返回异常（HTTP ${resp.status}），请稍后重试。`, view);
485	      return;
486	    }
487	    survey = await resp.json();
488	  } catch (err) {
489	    showEditLoadError(id, `网络错误：${err}。已保存的问卷内容未受影响，可重试加载。`, view);
490	    return;
491	  }
492	
493	  if (view !== activeView) return;
494	  app.replaceChildren(
495	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
496	    buildSurveyForm(survey, {}, view)
497	  );
498	}
499	
500	function route() {
501	  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
502	  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
503	  if (editMatch) renderEdit(Number(editMatch[1]));
504	  else if (detailMatch) renderDetail(Number(detailMatch[1]));
505	  else renderHome();
506	}
507	window.addEventListener("hashchange", route);
508	route();
509	</script>
510	</html>
511	"""
512	
513	
514	def validate_survey(obj):
515	    """Validate a decoded survey payload.
516	
517	    Returns (clean_survey, None) on success or (None, error_message) on failure.
518	    Strings are stored trimmed of surrounding whitespace; description keeps its
519	    raw value so Chinese, quotes and newlines are preserved.
520	    """
521	    if not isinstance(obj, dict):
522	        return None, "请求体必须是 JSON 对象"
523	    if "title" not in obj:
524	        return None, "缺少字段 title"
525	    title = obj["title"]
526	    if not isinstance(title, str):
527	        return None, "title 必须是字符串"
528	    title = title.strip()
529	    if not title:
530	        return None, "title 不能为空（或全为空白字符）"
531	
532	    description = obj.get("description", "")
533	    if not isinstance(description, str):
534	        return None, "description 必须是字符串"
535	
536	    if "questions" not in obj:
537	        return None, "缺少字段 questions"
538	    raw_questions = obj["questions"]
539	    if not isinstance(raw_questions, list):
540	        return None, "questions 必须是数组"
541	    if len(raw_questions) == 0:
542	        return None, "questions 至少需要一道题"
543	
544	    questions = []
545	    for index, raw_question in enumerate(raw_questions, start=1):
546	        location = f"第 {index} 题"
547	        if not isinstance(raw_question, dict):
548	            return None, f"{location}（questions[{index - 1}]）必须是对象"
549	
550	        if "type" not in raw_question:
551	            return None, f"{location}：缺少字段 type"
552	        question_type = raw_question["type"]
553	        if not isinstance(question_type, str):
554	            return None, f"{location}：type 必须是字符串"
555	        if question_type not in QUESTION_TYPES:
556	            shown = json.dumps(question_type, ensure_ascii=False)
557	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
558	
559	        if "title" not in raw_question:
560	            return None, f"{location}：缺少字段 title"
561	        question_title = raw_question["title"]
562	        if not isinstance(question_title, str):
563	            return None, f"{location}：title 必须是字符串"
564	        question_title = question_title.strip()
565	        if not question_title:
566	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
567	
568	        required = raw_question.get("required", False)
569	        if not isinstance(required, bool):
570	            return None, f"{location}：required 必须是布尔值"
571	
572	        raw_options = raw_question.get("options", [])
573	        if not isinstance(raw_options, list):
574	            return None, f"{location}：options 必须是数组"
575	
576	        options = []
577	        if question_type == "text":
578	            if len(raw_options) > 0:
579	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
580	        else:
581	            if len(raw_options) < 2:
582	                return None, f"{location}：单选题至少需要两个选项"
583	            seen = set()
584	            for option_index, raw_option in enumerate(raw_options, start=1):
585	                if not isinstance(raw_option, str):
586	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
587	                option = raw_option.strip()
588	                if not option:
589	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
590	                if option in seen:
591	                    shown = json.dumps(option, ensure_ascii=False)
592	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
593	                seen.add(option)
594	                options.append(option)
595	
596	        questions.append({
597	            "type": question_type,
598	            "title": question_title,
599	            "required": required,
600	            "options": options,
601	        })
602	
603	    return {
604	        "title": title,
605	        "description": description,
606	        "questions": questions,
607	    }, None
608	
609	
610	def main():
611	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
612	    commands = parser.add_subparsers(dest="command", required=True)
613	    serve = commands.add_parser("serve", help="Start the HTTP service")
614	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
615	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
616	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
617	    args = parser.parse_args()
618	    if not 0 <= args.port <= 65535:
619	        parser.error("port must be between 0 and 65535")
620	    args.data_dir.mkdir(parents=True, exist_ok=True)
621	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
622	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
623	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
624	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
625	    db_lock = threading.Lock()
626	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
627	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
628	    if "description" not in columns:
629	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
630	    database.execute(
631	        "CREATE TABLE IF NOT EXISTS questions ("
632	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
633	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
634	    )
635	    database.execute(
636	        "CREATE TABLE IF NOT EXISTS question_options ("
637	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
638	    )
639	    database.commit()
640	
641	    def survey_detail(survey_id):
642	        with db_lock:
643	            row = database.execute(
644	                "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
645	                (survey_id,),
646	            ).fetchone()
647	            if row is None:
648	                return None
649	            title, description = row
650	            questions = []
651	            question_rows = database.execute(
652	                "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
653	                (survey_id,),
654	            ).fetchall()
655	            for question_id, question_type, question_title, required in question_rows:
656	                options = [option_row[0] for option_row in database.execute(
657	                    "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
658	                    (question_id,),
659	                )]
660	                questions.append({
661	                    "type": question_type,
662	                    "title": question_title,
663	                    "required": bool(required),
664	                    "options": options,
665	                })
666	        return {
667	            "id": survey_id,
668	            "title": title,
669	            "description": description,
670	            "questions": questions,
671	        }
672	
673	    def save_survey(clean):
674	        """Insert the whole survey atomically; returns the new id."""
675	        with db_lock:
676	            try:
677	                cursor = database.execute(
678	                    "INSERT INTO surveys (title, description) VALUES (?, ?)",
679	                    (clean["title"], clean["description"]),
680	                )
681	                survey_id = cursor.lastrowid
682	                write_questions(survey_id, clean["questions"])
683	                database.commit()
684	                return survey_id
685	            except Exception:
686	                database.rollback()
687	                raise
688	
689	    def write_questions(survey_id, questions):
690	        """Replace all questions/options of a survey with the given ordered list."""
691	        old_question_ids = [row[0] for row in database.execute(
692	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
693	        )]
694	        if old_question_ids:
695	            placeholders = ",".join("?" for _ in old_question_ids)
696	            database.execute(
697	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
698	                old_question_ids,
699	            )
700	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
701	        for position, question in enumerate(questions):
702	            question_cursor = database.execute(
703	                "INSERT INTO questions (survey_id, position, type, title, required) "
704	                "VALUES (?, ?, ?, ?, ?)",
705	                (survey_id, position, question["type"], question["title"],
706	                 1 if question["required"] else 0),
707	            )
708	            question_id = question_cursor.lastrowid
709	            for option_position, option in enumerate(question["options"]):
710	                database.execute(
711	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
712	                    (question_id, option_position, option),
713	                )
714	
715	    def replace_survey(survey_id, clean):
716	        """Replace a whole survey atomically; keeps the same id.
717	
718	        Returns False when the survey does not exist (no record is created).
719	        """
720	        with db_lock:
721	            row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
722	            if row is None:
723	                return False
724	            try:
725	                database.execute(
726	                    "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
727	                    (clean["title"], clean["description"], survey_id),
728	                )
729	                write_questions(survey_id, clean["questions"])
730	                database.commit()
731	                return True
732	            except Exception:
733	                database.rollback()
734	                raise
735	
736	    class Handler(BaseHTTPRequestHandler):
737	        def respond(self, status, value, *, html=False, allow=None):
738	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
739	            self.send_response(status)
740	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
741	            self.send_header("Content-Length", str(len(payload)))
742	            if status == 405 and allow is not None:
743	                self.send_header("Allow", ", ".join(allow))
744	            self.end_headers()
745	            self.wfile.write(payload)
746	
747	        def list_surveys(self):
748	            with db_lock:
749	                records = [
750	                    {"id": row[0], "title": row[1]}
751	                    for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
752	                ]
753	            self.respond(200, {RESOURCE: records})
754	
755	        def read_payload(self):
756	            """Read and decode a JSON request body.
757	
758	            Returns (payload, None) or (None, error_message).
759	            """
760	            try:
761	                length = int(self.headers.get("Content-Length") or 0)
762	            except ValueError:
763	                length = -1
764	            if length < 0:
765	                return None, "Content-Length 无效"
766	            if length > MAX_BODY_BYTES:
767	                return None, "请求体过大"
768	            body = self.rfile.read(length) if length else b""
769	            try:
770	                return json.loads(body.decode("utf8")), None
771	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
772	                return None, f"请求体不是合法 JSON：{error}"
773	
774	        def create_survey(self):
775	            payload, error = self.read_payload()
776	            if error is not None:
777	                self.respond(400, {"error": error})
778	                return
779	
780	            clean, error = validate_survey(payload)
781	            if error is not None:
782	                self.respond(400, {"error": error})
783	                return
784	            try:
785	                survey_id = save_survey(clean)
786	            except sqlite3.DatabaseError as error:
787	                self.respond(500, {"error": f"保存失败：{error}"})
788	                return
789	            result = {"id": survey_id, **clean}
790	            self.respond(201, result)
791	
792	        def update_survey(self, survey_id):
793	            payload, read_error = self.read_payload()
794	            if survey_detail(survey_id) is None:
795	                # Editing a missing id is always 404 and must never create one.
796	                self.respond(404, {"error": "not found"})
797	                return
798	            if read_error is not None:
799	                self.respond(400, {"error": read_error})
800	                return
801	
802	            # Full replacement: validate before touching the stored draft so a
803	            # rejected request leaves the old survey exactly as it was.
804	            clean, error = validate_survey(payload)
805	            if error is not None:
806	                self.respond(400, {"error": error})
807	                return
808	            try:
809	                replace_survey(survey_id, clean)
810	            except sqlite3.DatabaseError as error:
811	                self.respond(500, {"error": f"保存失败：{error}"})
812	                return
813	            self.respond(200, {"id": survey_id, **clean})
814	
815	        def route(self):
816	            location = urlsplit(self.path).path
817	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
818	
819	            if location == "/api/surveys":
820	                allowed = ["GET", "POST"]
821	            elif location in ("/", "/health"):
822	                allowed = ["GET"]
823	            elif detail_match:
824	                allowed = ["GET", "PUT"]
825	            else:
826	                self.respond(404, {"error": "not found"})
827	                return
828	
829	            if self.command not in allowed:
830	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
831	                return
832	
833	            if location == "/":
834	                self.respond(200, PAGE, html=True)
835	            elif location == "/health":
836	                self.respond(200, {"status": "ok", "product": PRODUCT})
837	            elif location == "/api/surveys":
838	                if self.command == "POST":
839	                    self.create_survey()
840	                else:
841	                    self.list_surveys()
842	            else:
843	                survey_id = int(detail_match.group(1))
844	                if self.command == "PUT":
845	                    self.update_survey(survey_id)
846	                    return
847	                detail = survey_detail(survey_id)
848	                if detail is None:
849	                    self.respond(404, {"error": "not found"})
850	                else:
851	                    self.respond(200, detail)
852	
853	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
854	
855	    def stop(_signal, _frame):
856	        raise KeyboardInterrupt
857	
858	    signal.signal(signal.SIGTERM, stop)
859	    server = None
860	    try:
861	        # 每个连接在独立线程中处理：浏览器预先建立但暂不发送请求的备用连接、
862	        # 或只发了部分请求头/正文就暂停的连接，只会占用自己的线程，不会拖住
863	        # 其他连接上的完整请求。daemon_threads 保证退出时不被这些空闲连接卡住。
864	        server = ThreadingHTTPServer((args.host, args.port), Handler)
865	        host, port = server.server_address[:2]
866	        address = f"[{host}]" if ":" in host else host
867	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
868	        server.serve_forever()
869	    except KeyboardInterrupt:
870	        pass
871	    finally:
872	        if server is not None:
873	            server.server_close()
874	        database.close()
875	
876	
877	if __name__ == "__main__":
878	    main()
879

