}

async function renderEdit(id) {
  const view = ++activeView;
  app.replaceChildren(
    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
    h("p", {class: "muted", id: "edit-status"}, "加载中…")
  );

  let survey;
  try {
